const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs');
test('seaside grammar keeps the six-resident model and marks coastal work illustrative',async()=>{const {SEASIDE_SCENES,seasideRecipe,describeSeaside}=await import('../seaside-scenes.js');for(const preset of Object.keys(SEASIDE_SCENES.seaside.presets)){const a=seasideRecipe(preset,41);assert.deepEqual(a,seasideRecipe(preset,41));assert.deepEqual(SEASIDE_SCENES.seaside.capabilities,{housing:6});assert.equal(a.generator,'seaside-composer');assert(a.requirements[0].items.every(i=>i.purpose&&Number.isFinite(i.x)&&Number.isFinite(i.z)));assert.match(describeSeaside(preset),/illustrative/);assert.match(SEASIDE_SCENES.seaside.limitations.join(' '),/visual only/);}});
test('imported coastal files match reviewed immutable manifest hashes',()=>{const crypto=require('node:crypto'),m=JSON.parse(fs.readFileSync('coastal-assets/manifest.json'));assert.equal(m.count,62);assert.deepEqual(m.correctiveRevisions,['CE-076','CE-077']);for(const a of m.assets){assert.equal(a.reviewEvidence.passed,true,a.id);assert.equal(a.validationEvidence.passed,true,a.id);assert.equal(a.reviewEvidence.evidence.sha256,a.files.png.sha256);assert.equal(crypto.createHash('sha256').update(fs.readFileSync('coastal-assets/'+a.id+'.glb')).digest('hex'),a.files.glb.sha256);}});
